#!/bin/bash
set -eo pipefail
umask 077
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_CACHE'
import base64,datetime,hashlib,io,json,os,pathlib,subprocess,time,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/catalog_inventory_v1')
assert root.parent.resolve(strict=True)==root.parent and not root.exists() and not root.is_symlink()
packed=base64.b64decode('',validate=True)
assert len(packed)==18079 and hashlib.sha256(packed).hexdigest()=='7c722d7ce33dd5045e46b033004bf6b489bc734795a5767e88f0c922646558ff'
table=json.loads('{"inventory_retained_catalog_v1.py":{"bytes":12558,"sha256":"f20f1b8e05056935c9eebfc86f8a69a38046d73b64ddaf8a35415c64117241cf"},"CACHE_INVENTORY_CONTRACT.json":{"bytes":90638,"sha256":"c8cdeb90487f5e9a6cf435c1f56973bda70435ebe2a3423a30f26e8d910d3ec1"}}')
root.mkdir(mode=0o700)
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 assert archive.namelist()==sorted(table) and len(table)==2 and len(set(archive.namelist()))==2
 assert sum(i.file_size for i in archive.infolist())<=524288
 for name in archive.namelist():
  assert '/' not in name and '\\' not in name and name not in ('','.','..')
  raw=archive.read(name)
  assert len(raw)==table[name]['bytes'] and hashlib.sha256(raw).hexdigest()==table[name]['sha256']
  with (root/name).open('xb') as output:output.write(raw)
print('OWN_CACHE_PAYLOAD_VERIFIED=2',flush=True)
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='',
 OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1',NUMEXPR_NUM_THREADS='1')
began=time.monotonic()
started=dict(server_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),new_http_requests=0,
 scientific_array_reads=0,new_slurm_jobs=0,model_calls=0,automatic_checks_enabled=False)
with (root/'INVENTORY_STARTED.json').open('x') as stream:json.dump(started,stream,indent=2)
with (root/'inventory.stdout').open('xb') as stdout,(root/'inventory.stderr').open('xb') as stderr:
 outcome=subprocess.run(['timeout','--signal=TERM','--kill-after=5s','75s',
  '/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python','-B',str(root/'inventory_retained_catalog_v1.py')],
  cwd=root,env=env,stdout=stdout,stderr=stderr)
execution=dict(exit_code=outcome.returncode,elapsed_seconds=time.monotonic()-began,
 child_result_present=(root/'CACHE_INVENTORY_RESULT.json').is_file(),new_http_requests=0,
 scientific_array_reads=0,new_slurm_jobs=0,model_calls=0,original_cache_modified=False,
 program_identity=table['inventory_retained_catalog_v1.py'],contract_identity=table['CACHE_INVENTORY_CONTRACT.json'])
with (root/'INVENTORY_EXECUTION.json').open('x') as stream:json.dump(execution,stream,indent=2)
allowed=['CACHE_IDENTITIES.json','CACHE_REQUESTS.json','CACHE_PERIODS.json','CACHE_INVENTORY_RESULT.json',
 'CACHE_INVENTORY_FAILURE.json','INVENTORY_STARTED.json','INVENTORY_EXECUTION.json','inventory.stdout','inventory.stderr']
files={}
used=0
for name in allowed:
 path=root/name
 if not path.exists():continue
 assert path.is_file() and not path.is_symlink() and path.resolve(strict=True)==path
 size=path.stat().st_size
 assert size<= (65536 if name.endswith(('.stdout','.stderr')) else 8388608)
 assert used+size<=8388608
 raw=path.read_bytes()
 assert len(raw)==size
 used+=size
 files[name]=dict(path=str(path),bytes=size,sha256=hashlib.sha256(raw).hexdigest())
index=(json.dumps(files,indent=2)+'\n').encode()
assert used+len(index)<=8388608
delivery=root/'DELIVERY_seq12_CACHE.zip'
with zipfile.ZipFile(delivery,'x',compression=zipfile.ZIP_DEFLATED) as archive:
 archive.writestr('REPORT_FILES.json',index)
 for name in files:archive.write(root/name,arcname=name)
assert delivery.stat().st_size<=1048576
raw=delivery.read_bytes()
print('OWN_CACHE_INVENTORY_EXIT='+str(outcome.returncode))
print('OWN_CACHE_FILE=DELIVERY_seq12_CACHE.zip')
print('OWN_CACHE_BYTES='+str(len(raw)))
print('OWN_CACHE_SHA256='+hashlib.sha256(raw).hexdigest())
print('OWN_CACHE_BASE64_BEGIN')
print(base64.b64encode(raw).decode())
print('OWN_CACHE_BASE64_END')
print('OWN_CACHE_INVENTORY_DONE')
PY_CACHE
